delete from packages where slug = 'turf-weekly-large-area';
update service_tiers t set service_slug = r.service_slug, label = r.label, min_qty = r.min_qty, max_qty = r.max_qty, price_cents = r.price_cents, price_suffix = r.price_suffix,
  requires_quote = r.requires_quote, price_is_from = r.price_is_from, sort_order = r.sort_order, status = r.status
  from _s, jsonb_populate_recordset(null::service_tiers, _s.j) r where _s.t = 'service_tiers' and t.id = r.id;
delete from service_tiers where service_slug in ('yard-sanitizing', 'extra-yard-work', 'turf-deep-clean') or (service_slug = 'weekly-turf-maintenance' and label = 'Over 800 sq ft');
delete from services where slug in ('yard-sanitizing', 'extra-yard-work', 'turf-deep-clean');
update services t set name = r.name, short_name = r.short_name, price_basis = r.price_basis, basis_label = r.basis_label, pricing_note = r.pricing_note, status = r.status,
  meta_title = r.meta_title, meta_description = r.meta_description, h1 = r.h1, intro = r.intro, what_includes = r.what_includes, who_its_for = r.who_its_for, faqs = r.faqs, related_slugs = r.related_slugs
  from _s, jsonb_populate_recordset(null::services, _s.j) r where _s.t = 'services' and t.slug = r.slug;
update packages t set name = r.name, short_label = r.short_label, monthly_price_cents = r.monthly_price_cents, visits_per_month = r.visits_per_month, derivation = r.derivation, status = r.status, featured = r.featured
  from _s, jsonb_populate_recordset(null::packages, _s.j) r where _s.t = 'packages' and t.id = r.id;
update offers t set name = r.name from _s, jsonb_populate_recordset(null::offers, _s.j) r where _s.t = 'offers' and t.id = r.id;
